import * as Effect from "effect/Effect";import * as Layer from "effect/Layer";import * as Stream from "effect/Stream";import * as LanguageModel from "effect/ai/LanguageModel";const model=Layer.effect(LanguageModel.LanguageModel,LanguageModel.make({generateText:()=>Effect.succeed([{type:"text",text:"hello"},{type:"finish",reason:"stop",usage:{inputTokens:{total:1},outputTokens:{total:1}}}]),streamText:()=>Stream.empty}));Effect.runPromise((LanguageModel.generateText({prompt:"Hello"}).pipe(Effect.map(r=>r.text),Effect.provide(model))).pipe(Effect.tap(value=>Effect.sync(()=>console.log(JSON.stringify(value))))))
